# Liebermann, Gesetze I pp. 659–660: Lond 32 E 1–E 6; ECf 33 (ECf retr 33 runs on to p. 661: see p661.py)
D = lambda de, en: (de, en)
LOND_ED = 'This passage is not part of ECf or ECf retr: it is one of the additions of the London collection (Leges Anglorum s. XIII in. Londoniis collectae), which Liebermann prints across the page as an insertion into ECf retr. 32 (32 A–E, pp. 655–660). The dictionary cites it as “ECf 32 E …”, so it is kept with ECf here.'
LD = D('<i>fehlt Ld</i>', 'lacking in Ld')
B = D('Bryt. <i>Ld</i>', 'Bryt. Ld')
FF = D('<i>wie</i> 32 C 4', 'as at 32 C 4')
def L(n, text, notes, page=660, margin=None, extra=None, **kw):
    c = {'code': 'ECf', 'n': n, 'page': page, 'keys': ['ECf ' + n], 'text': text, 'notes': notes, 'editorial': [LOND_ED] + (extra or [])}
    if margin: c['margin'] = margin
    c.update(kw)
    return c
